import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

await import('./inline-handler-safety.mjs');

const root=path.resolve(new URL('..',import.meta.url).pathname);
const read=p=>fs.readFileSync(path.join(root,p),'utf8');
const exists=p=>fs.existsSync(path.join(root,p));

for(const name of fs.readdirSync(path.join(root,'supabase','migrations'))){
  if(!name.endsWith('.sql'))continue;
  const sql=read(path.join('supabase','migrations',name));
  assert.ok(!/^\\s*\\$function\\$\\s*$/m.test(sql),`migration ${name} possui terminador $function$ sem ponto e vírgula`);
}

const html=read('index.html');
const refs=[...html.matchAll(/(?:src|href)="(\.\/[^"#?]+)"/g)].map(m=>m[1].replace(/^\.\//,''));
for(const ref of refs) assert.ok(exists(ref),`asset ausente no index: ${ref}`);

const manifest=JSON.parse(read('manifest.webmanifest'));
for(const icon of manifest.icons||[]) assert.ok(exists(icon.src.replace(/^\.\//,'')),`ícone do manifest ausente: ${icon.src}`);
assert.equal(manifest.short_name,'TAMÃO','PWA deve expor a nova marca pública');
assert.equal(manifest.theme_color,'#0d6b4b','manifest deve usar o verde institucional TAMÃO');
assert.match(html,/TAMÃO — Pediu\? Tá na mão\./,'title deve carregar marca e assinatura');

const sw=read('sw.js');
const swAssets=[...sw.matchAll(/'\.\/([^']*)'/g)].map(m=>m[1]).filter(Boolean);
for(const asset of swAssets){
  if(asset.includes('#')) continue;
  assert.ok(exists(asset),`asset do service worker ausente: ${asset}`);
}

