const functionRoot=path.join(root,'supabase/functions');
for(const entry of fs.readdirSync(functionRoot,{withFileTypes:true})){
  if(!entry.isDirectory()||entry.name==='_shared')continue;
  const file=path.join(functionRoot,entry.name,'index.ts');
  if(!fs.existsSync(file))continue;
  const source=fs.readFileSync(file,'utf8');
  assert.ok(source.includes('jsr:@supabase/functions-js@2.117.2/edge-runtime.d.ts'),entry.name+' precisa fixar functions-js');
  assert.ok(source.includes('npm:@supabase/supabase-js@2.117.2'),entry.name+' precisa fixar supabase-js');
  if(entry.name==='capture-prelaunch-lead'){
    assert.ok(source.includes('raw.length>16000'),entry.name+' precisa limitar JSON');
    assert.ok(source.includes('capture_prelaunch_lead_idempotent'),entry.name+' precisa usar autoridade transacional de retry');
    assert.ok(leadRetryOrdering.includes('consume_prelaunch_lead_quota'),entry.name+' precisa manter quota dentro da autoridade server-side');
    assert.ok(source.includes('ALLOWED_ORIGINS')&&source.includes('originAllowed'),entry.name+' precisa restringir origem explicitamente');
    assert.ok(source.includes('body.website'),entry.name+' precisa manter honeypot');
  }else if(entry.name==='submit-public-request'){
    assert.ok(source.includes('raw.length>16000'),entry.name+' precisa limitar JSON');
    assert.ok(source.includes('consume_prelaunch_lead_quota'),entry.name+' precisa aplicar quota server-side');
    assert.ok(source.includes('ALLOWED_ORIGINS')&&source.includes('originAllowed'),entry.name+' precisa restringir origem explicitamente');
    assert.ok(source.includes('body.website'),entry.name+' precisa manter honeypot');
  }else if(entry.name==='capture-marketing-event'){
    assert.ok(source.includes('raw.length>6000'),entry.name+' precisa limitar JSON com teto reduzido');
    assert.ok(source.includes('consume_prelaunch_lead_quota'),entry.name+' precisa aplicar quota server-side');
    assert.ok(source.includes('ALLOWED_ORIGINS')&&source.includes('originAllowed'),entry.name+' precisa restringir origem explicitamente');
    assert.ok(source.includes('EVENT_TYPES')&&source.includes('AUDIENCES'),entry.name+' precisa manter allowlists de evento e público');
    assert.ok(source.includes('record_prelaunch_marketing_event'),entry.name+' precisa gravar somente pelo RPC agregado');
  }else if(entry.name==='billing-payment-webhook'){
    assert.ok(source.includes('MAX_BODY_BYTES=16384')&&source.includes('TextEncoder().encode(rawBody).byteLength>MAX_BODY_BYTES'),entry.name+' precisa limitar o corpo bruto antes do parse');
    assert.ok(source.includes('x-tamao-signature')&&source.includes('hmacSha256Hex')&&source.includes('constantTimeEqualHex'),entry.name+' precisa autenticar o payload bruto por HMAC');
    assert.ok(source.includes('MAX_SKEW_SECONDS=300')&&source.includes('STALE_WEBHOOK'),entry.name+' precisa bloquear replay temporal');
    assert.ok(source.includes('ingest_merchant_billing_payment_event'),entry.name+' precisa usar autoridade transacional server-only');
  }else if(entry.name==='billing-payment-webhook-woovi'){
    assert.ok(source.includes('MAX_BODY_BYTES=65536')&&source.includes('TextEncoder().encode(rawBody).byteLength>MAX_BODY_BYTES'),entry.name+' precisa limitar o corpo bruto antes do parse');
    assert.ok(source.includes('x-webhook-signature')&&source.includes('verifyWooviSignature(rawBody,signature)')&&source.includes('RSASSA-PKCS1-v1_5'),entry.name+' precisa autenticar o payload bruto com RSA-SHA256');
    assert.ok(source.includes('WOOVI_WEBHOOK_AUTHORIZATION')&&source.includes('constantTimeEqual(authorization,expectedAuthorization)'),entry.name+' precisa exigir token privado do webhook');
    assert.ok(source.includes('WOOVI_COMPANY_ID')&&source.includes('WOOVI_COMPANY_MISMATCH'),entry.name+' precisa vincular a entrega à empresa configurada');
    assert.ok(source.includes('OPENPIX:TRANSACTION_RECEIVED')&&source.includes('ingest_merchant_billing_payment_event'),entry.name+' precisa aceitar apenas Pix recebido e delegar ao matcher server-only');
  }else{
    assert.ok(source.includes('readJsonBody(req)'),entry.name+' precisa limitar JSON');
    assert.ok(source.includes('enforceApiQuota(admin'),entry.name+' precisa aplicar quota server-side');
  }
  if(entry.name==='complete-delivery'){
    assert.ok(source.includes('body.paymentConfirmed!==true'),'complete-delivery deve exigir confirmação de pagamento');
    assert.ok(source.includes('paymentConfirmed:true'),'fingerprint idempotente deve incluir confirmação de pagamento');
  }

}


